CREATE TABLE IF NOT EXISTS templates (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  slug TEXT UNIQUE NOT NULL,
  name TEXT NOT NULL,
  category TEXT NOT NULL,
  description TEXT,
  html TEXT NOT NULL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);

INSERT OR REPLACE INTO templates (slug, name, category, description, html) VALUES ('hero-minimal', 'Hero Minimal', 'hero', 'Centered heading dengan CTA. Sesuai untuk landing page ringkas.', '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Hero</title><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-white"><section class="max-w-4xl mx-auto px-6 py-24 text-center"><h1 class="text-5xl md:text-6xl font-bold text-gray-900 mb-6 tracking-tight">Build something great</h1><p class="text-lg text-gray-600 mb-8 max-w-2xl mx-auto">A clean starting point for your next project. Fast, modern, easy to customize.</p><a href="#" class="inline-block bg-black text-white px-8 py-3 rounded-full font-medium hover:opacity-80 transition">Get started</a></section></body></html>');

INSERT OR REPLACE INTO templates (slug, name, category, description, html) VALUES ('hero-split', 'Hero Split', 'hero', 'Hero 2-column: text kiri, visual kanan.', '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Hero Split</title><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-white"><section class="max-w-6xl mx-auto px-6 py-24 grid md:grid-cols-2 gap-12 items-center"><div><h1 class="text-5xl font-bold text-gray-900 mb-6 leading-tight">Launch faster with our platform</h1><p class="text-lg text-gray-600 mb-8">Everything you need to build, ship, and scale your next big idea.</p><div class="flex gap-4"><a href="#" class="bg-black text-white px-6 py-3 rounded-full font-medium hover:opacity-80">Start free</a><a href="#" class="border border-gray-300 text-gray-900 px-6 py-3 rounded-full font-medium hover:bg-gray-50">Learn more</a></div></div><div class="aspect-square bg-gradient-to-br from-gray-100 to-gray-300 rounded-3xl"></div></section></body></html>');

INSERT OR REPLACE INTO templates (slug, name, category, description, html) VALUES ('hero-gradient', 'Hero Gradient', 'hero', 'Hero dengan background gradient mesra.', '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Hero Gradient</title><script src="https://cdn.tailwindcss.com"></script></head><body><section class="min-h-screen bg-gradient-to-br from-indigo-600 via-purple-600 to-pink-500 flex items-center justify-center px-6"><div class="text-center text-white max-w-3xl"><h1 class="text-6xl font-bold mb-6 tracking-tight">Design without limits</h1><p class="text-xl text-white/90 mb-10">The toolkit for creators who ship. Beautiful by default, powerful when you need it.</p><a href="#" class="inline-block bg-white text-gray-900 px-8 py-4 rounded-full font-semibold hover:bg-gray-100 transition">Get started free</a></div></section></body></html>');

INSERT OR REPLACE INTO templates (slug, name, category, description, html) VALUES ('features-grid', 'Features Grid', 'features', 'Grid 3-column features dengan icon.', '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Features</title><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-white"><section class="max-w-6xl mx-auto px-6 py-24"><div class="text-center mb-16"><h2 class="text-4xl font-bold text-gray-900 mb-4">Everything you need</h2><p class="text-lg text-gray-600">Powerful features, simple pricing.</p></div><div class="grid md:grid-cols-3 gap-8"><div class="p-8 rounded-2xl border border-gray-200 hover:border-gray-900 transition"><div class="w-12 h-12 bg-gray-900 rounded-xl mb-6"></div><h3 class="text-xl font-semibold mb-3">Fast setup</h3><p class="text-gray-600">Get up and running in under 2 minutes.</p></div><div class="p-8 rounded-2xl border border-gray-200 hover:border-gray-900 transition"><div class="w-12 h-12 bg-gray-900 rounded-xl mb-6"></div><h3 class="text-xl font-semibold mb-3">Secure by default</h3><p class="text-gray-600">Enterprise-grade security out of the box.</p></div><div class="p-8 rounded-2xl border border-gray-200 hover:border-gray-900 transition"><div class="w-12 h-12 bg-gray-900 rounded-xl mb-6"></div><h3 class="text-xl font-semibold mb-3">Scales with you</h3><p class="text-gray-600">From side project to millions of users.</p></div></div></section></body></html>');

INSERT OR REPLACE INTO templates (slug, name, category, description, html) VALUES ('pricing-3tier', 'Pricing 3-Tier', 'pricing', 'Pricing table 3 pakej dengan highlight.', '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pricing</title><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-gray-50"><section class="max-w-6xl mx-auto px-6 py-24"><div class="text-center mb-16"><h2 class="text-4xl font-bold text-gray-900 mb-4">Simple pricing</h2><p class="text-lg text-gray-600">Choose the plan that fits.</p></div><div class="grid md:grid-cols-3 gap-6"><div class="bg-white p-8 rounded-2xl border border-gray-200"><div class="text-sm font-semibold text-gray-500 uppercase mb-2">Free</div><div class="text-4xl font-bold text-gray-900 mb-6">RM0<span class="text-lg font-normal text-gray-500">/mo</span></div><ul class="space-y-3 mb-8 text-gray-600"><li>3 websites</li><li>100MB storage</li><li>Community support</li></ul><a href="#" class="block text-center border border-gray-300 py-3 rounded-full font-medium hover:bg-gray-50">Start free</a></div><div class="bg-gray-900 p-8 rounded-2xl text-white relative"><div class="absolute top-4 right-4 text-xs bg-white/10 px-3 py-1 rounded-full">Popular</div><div class="text-sm font-semibold text-gray-300 uppercase mb-2">Pro</div><div class="text-4xl font-bold mb-6">RM29<span class="text-lg font-normal text-gray-400">/mo</span></div><ul class="space-y-3 mb-8 text-gray-300"><li>20 websites</li><li>5GB storage</li><li>Custom domain</li><li>Priority support</li></ul><a href="#" class="block text-center bg-white text-gray-900 py-3 rounded-full font-medium hover:bg-gray-100">Get Pro</a></div><div class="bg-white p-8 rounded-2xl border border-gray-200"><div class="text-sm font-semibold text-gray-500 uppercase mb-2">Business</div><div class="text-4xl font-bold text-gray-900 mb-6">RM99<span class="text-lg font-normal text-gray-500">/mo</span></div><ul class="space-y-3 mb-8 text-gray-600"><li>Unlimited sites</li><li>100GB storage</li><li>Team collaboration</li></ul><a href="#" class="block text-center border border-gray-300 py-3 rounded-full font-medium hover:bg-gray-50">Contact us</a></div></div></section></body></html>');

INSERT OR REPLACE INTO templates (slug, name, category, description, html) VALUES ('faq-accordion', 'FAQ Accordion', 'faq', 'Soalan lazim dengan collapsible detail.', '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FAQ</title><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-white"><section class="max-w-3xl mx-auto px-6 py-24"><h2 class="text-4xl font-bold text-gray-900 mb-12 text-center">Frequently asked questions</h2><div class="space-y-4"><details class="group border border-gray-200 rounded-xl p-6"><summary class="flex justify-between items-center cursor-pointer font-semibold text-gray-900">How do I get started?<span class="text-2xl group-open:rotate-45 transition">+</span></summary><p class="mt-4 text-gray-600">Sign up for a free account, choose a template, and publish your first site in minutes.</p></details><details class="group border border-gray-200 rounded-xl p-6"><summary class="flex justify-between items-center cursor-pointer font-semibold text-gray-900">Can I use my own domain?<span class="text-2xl group-open:rotate-45 transition">+</span></summary><p class="mt-4 text-gray-600">Yes, all paid plans support custom domains with automatic SSL.</p></details><details class="group border border-gray-200 rounded-xl p-6"><summary class="flex justify-between items-center cursor-pointer font-semibold text-gray-900">Is there a free plan?<span class="text-2xl group-open:rotate-45 transition">+</span></summary><p class="mt-4 text-gray-600">Absolutely. Our free plan includes 3 websites with no credit card required.</p></details></div></section></body></html>');

INSERT OR REPLACE INTO templates (slug, name, category, description, html) VALUES ('cta-newsletter', 'CTA Newsletter', 'cta', 'Section subscribe email untuk capture leads.', '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Newsletter</title><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-white"><section class="max-w-4xl mx-auto px-6 py-24"><div class="bg-gray-900 rounded-3xl p-12 md:p-16 text-center"><h2 class="text-3xl md:text-4xl font-bold text-white mb-4">Stay in the loop</h2><p class="text-gray-400 mb-8 max-w-xl mx-auto">Get product updates, tips, and stories delivered to your inbox. No spam, ever.</p><form class="flex flex-col sm:flex-row gap-3 max-w-md mx-auto"><input type="email" placeholder="you@example.com" class="flex-1 px-5 py-3 rounded-full bg-white/10 border border-white/20 text-white placeholder-gray-500 focus:outline-none focus:border-white"><button class="bg-white text-gray-900 px-6 py-3 rounded-full font-medium hover:bg-gray-100">Subscribe</button></form></div></section></body></html>');

INSERT OR REPLACE INTO templates (slug, name, category, description, html) VALUES ('testimonials-cards', 'Testimonials Cards', 'testimonials', 'Review pelanggan dalam kad 3-column.', '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Testimonials</title><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-gray-50"><section class="max-w-6xl mx-auto px-6 py-24"><h2 class="text-4xl font-bold text-gray-900 mb-16 text-center">Loved by thousands</h2><div class="grid md:grid-cols-3 gap-6"><div class="bg-white p-8 rounded-2xl border border-gray-200"><p class="text-gray-700 mb-6 leading-relaxed">This tool changed how we ship websites. From idea to live in under an hour.</p><div class="flex items-center gap-4"><div class="w-12 h-12 bg-gray-200 rounded-full"></div><div><div class="font-semibold text-gray-900">Ahmad Rizwan</div><div class="text-sm text-gray-500">Founder, Kopi Co</div></div></div></div><div class="bg-white p-8 rounded-2xl border border-gray-200"><p class="text-gray-700 mb-6 leading-relaxed">The cleanest UI I have used. My clients love how fast their sites load.</p><div class="flex items-center gap-4"><div class="w-12 h-12 bg-gray-200 rounded-full"></div><div><div class="font-semibold text-gray-900">Sarah Lim</div><div class="text-sm text-gray-500">Designer</div></div></div></div><div class="bg-white p-8 rounded-2xl border border-gray-200"><p class="text-gray-700 mb-6 leading-relaxed">Finally a platform that does not get in the way. Simple, fast, reliable.</p><div class="flex items-center gap-4"><div class="w-12 h-12 bg-gray-200 rounded-full"></div><div><div class="font-semibold text-gray-900">Kumar Raj</div><div class="text-sm text-gray-500">Developer</div></div></div></div></div></section></body></html>');

INSERT OR REPLACE INTO templates (slug, name, category, description, html) VALUES ('contact-form', 'Contact Form', 'contact', 'Form hubungi dengan 2-column layout.', '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Contact</title><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-white"><section class="max-w-6xl mx-auto px-6 py-24 grid md:grid-cols-2 gap-16"><div><h1 class="text-5xl font-bold text-gray-900 mb-6">Get in touch</h1><p class="text-lg text-gray-600 mb-10">We would love to hear from you. Fill up the form and we will respond within 24 hours.</p><div class="space-y-4 text-gray-600"><div class="flex gap-3"><span class="font-medium text-gray-900 w-20">Email</span><span>hello@example.com</span></div><div class="flex gap-3"><span class="font-medium text-gray-900 w-20">Phone</span><span>+60 12-345 6789</span></div><div class="flex gap-3"><span class="font-medium text-gray-900 w-20">Address</span><span>Kuala Lumpur, Malaysia</span></div></div></div><form class="space-y-4"><input type="text" placeholder="Your name" class="w-full px-5 py-3 border border-gray-300 rounded-full focus:outline-none focus:border-gray-900"><input type="email" placeholder="Your email" class="w-full px-5 py-3 border border-gray-300 rounded-full focus:outline-none focus:border-gray-900"><textarea placeholder="Your message" rows="5" class="w-full px-5 py-3 border border-gray-300 rounded-2xl focus:outline-none focus:border-gray-900 resize-none"></textarea><button class="w-full bg-gray-900 text-white py-3 rounded-full font-medium hover:bg-gray-800">Send message</button></form></section></body></html>');

INSERT OR REPLACE INTO templates (slug, name, category, description, html) VALUES ('footer-simple', 'Footer Simple', 'footer', 'Footer multi-column dengan copyright.', '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Footer</title><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-white"><footer class="bg-gray-900 text-gray-400"><div class="max-w-6xl mx-auto px-6 py-16 grid md:grid-cols-4 gap-10"><div class="md:col-span-1"><div class="text-white text-xl font-bold mb-4">Brand</div><p class="text-sm">Building the future of the web, one site at a time.</p></div><div><div class="text-white font-semibold mb-4">Product</div><ul class="space-y-2 text-sm"><li><a href="#" class="hover:text-white">Features</a></li><li><a href="#" class="hover:text-white">Pricing</a></li><li><a href="#" class="hover:text-white">Docs</a></li></ul></div><div><div class="text-white font-semibold mb-4">Company</div><ul class="space-y-2 text-sm"><li><a href="#" class="hover:text-white">About</a></li><li><a href="#" class="hover:text-white">Blog</a></li><li><a href="#" class="hover:text-white">Careers</a></li></ul></div><div><div class="text-white font-semibold mb-4">Legal</div><ul class="space-y-2 text-sm"><li><a href="#" class="hover:text-white">Privacy</a></li><li><a href="#" class="hover:text-white">Terms</a></li><li><a href="#" class="hover:text-white">Security</a></li></ul></div></div><div class="border-t border-gray-800 py-6 text-center text-sm">2026 Brand. All rights reserved.</div></footer></body></html>');
